{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/job-board.json
    Open jobs as cards in two columns, grouped by department, or as a table: the title, the department, the place, the type, an optional salary and an apply link. Axes: layout (grid, grouped, table), salary (show, hide), tone.
    Props (p): id, title, lead, jobs, departments, labels, layout, salary, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_jobs = ($p['jobs'] ?? null)}
{var $v_departments = ($p['departments'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_salary = ($p['salary'] ?? 'hide')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_12}
  {if ui_t(ui_eq($v_layout, 'grouped'))}
    {capture $c_11}
      {foreach ui_l($v_departments) as $v_d}
        {capture $c_10}
          {capture $c_3}
            {capture $c_1}
              {=ui_text(ui_get($v_d, ['name']))}
            {/capture}
            {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'lg', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
            {capture $c_2}
              {=ui_text(ui_tpl(ui_get($v_labels, ['count']), [ui_len(ui_where($v_jobs, 'dept', ui_get($v_d, ['id'])))]))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
          {/capture}
          {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'baseline', 'Justify' => 'between'], 'children' => $c_3])|noescape}
          {capture $c_9}
            {foreach ui_l(ui_where($v_jobs, 'dept', ui_get($v_d, ['id']))) as $v_j}
              {capture $c_8}
                {capture $c_6}
                  {capture $c_4}
                    {=ui_text(ui_get($v_j, ['title']))}
                  {/capture}
                  {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/careers', 'Variant' => 'default', 'Class' => 'font-medium'], 'children' => $c_4])|noescape}
                  {capture $c_5}
                    {=ui_text(ui_tpl('{0}, {1}', [ui_get($v_j, ['location']), ui_get($v_j, ['type'])]))}
                  {/capture}
                  {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
                {/capture}
                {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0'], 'children' => $c_6])|noescape}
                {capture $c_7}
                  {=ui_text(ui_get($v_j, ['type']))}
                {/capture}
                {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'outline', 'Size' => 'default'], 'children' => $c_7])|noescape}
              {/capture}
              {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex flex-wrap items-center justify-between gap-4 border-b border-border py-4', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_8])|noescape}
            {/foreach}
          {/capture}
          {=ui_include('ui/list/list.latte', ['p' => ['Tag' => 'ul', 'Class' => 'flex flex-col'], 'children' => $c_9])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'group'])], 'children' => $c_10])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '8', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'groups'])], 'children' => $c_11])|noescape}
  {else}
    {=ui_include('blocks/job-cards.latte', ['p' => ['jobs' => $v_jobs, 'departments' => $v_departments, 'labels' => $v_labels, 'layout' => $v_layout, 'salary' => $v_salary]])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'measure' => (ui_t(ui_eq($v_layout, 'grouped')) ? '3xl' : 'default'), 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_12])|noescape}
